COOKIE_NAME = "ol_ui"
# v0.21.x persistent UI session. The legacy ol_ui cookie carries the
# CURRENT daemon's UI token, which rotates whenever the on-disk token
# file can't be loaded (lockbox key drift, manual file delete, etc.).
# ol_session is keyed off a uuid recorded in the ui_sessions table —
# state.db survives daemon restarts, so old browser tabs keep
# working without bouncing the user to the "access denied" page.
# ol_session_present is a parallel JS-visible marker (NO secret in
# it; just "yes a session cookie exists") so the access-denied page
# can decide to auto-reload silently instead of dead-ending.
SESSION_COOKIE_NAME = "ol_session"
SESSION_PRESENT_MARKER_COOKIE = "ol_session_present"
SESSION_COOKIE_MAX_AGE_SECONDS = 60 * 60 * 24 * 30  # 30 days
SESSION_ABSOLUTE_MAX_AGE_SECONDS = SESSION_COOKIE_MAX_AGE_SECONDS
SESSION_TOUCH_INTERVAL_MS = 60 * 1000
# Browser WebSocket APIs cannot set an Authorization header.  The owner event
# stream therefore carries its bearer as a second WebSocket subprotocol item
# while the server selects only this constant, non-secret protocol.  Keeping
# the credential out of the URL avoids access-log, history, and referrer leaks.
OWNER_WS_PROTOCOL = "one-link.owner.v1"
OWNER_WS_BEARER_PROTOCOL_PREFIX = "one-link.bearer."
# v0.21.x user-controllable toggles. Defaults match shipped behavior
# (persistence ON for "just works" UX; labels ON for readable
# Settings list). User can flip either via Privacy pane — turning
# persistence OFF wipes the table + stops issuing cookies; turning
# labels OFF stops storing UA fingerprint on new + future sessions
# (and clears existing labels in the same write).
SESSION_PERSISTENCE_SETTING = "ui_session_persistence_enabled"
SESSION_LABELS_SETTING = "ui_session_labels_enabled"
# Revoked rows are auto-pruned after this many days so the audit
# history doesn't grow without bound on an active device.
SESSION_AUTOPRUNE_REVOKED_AFTER_DAYS = 7
MAX_JSON_REQUEST_BYTES = 256 * 1024
MAX_REQUEST_TARGET_BYTES = 8 * 1024
RATE_LIMIT_WINDOW_SECONDS = 60.0
