                "CALL_SDP_ANSWER",
                "CALL_SDP_OFFER",
                "CAPABILITY_GRANT",
                "CAPS",
                "CAPSULE_CHUNK",
                "CAPSULE_COMPLETE",
                "CAPSULE_OFFER",
                "CAPSULE_RECEIPT",
                "CHUNK_DATA",
                "CHUNK_HAVE",
                "CHUNK_PULL",
