                "FILE_COMMIT",
                "FILE_COMMIT_VERIFYING",
                "FILE_DECLINED",
                "FILE_DONE",
                "FILE_NATIVE_CHUNK",
                "FILE_OFFER",
                "FILE_OFFER_BATCH",
                "FILE_OFFER_HELD",
                "FILE_PROVENANCE",
                "FILE_WANTS",
                "FOLDER_OFFER_ACCEPTED",
                "FOLDER_OFFER_DECLINED",
                "FOLDER_SYNC_COMMIT",
                "FOLDER_SYNC_VERIFY",
                "GROUP_EVENT",
                "GROUP_KEY_OFFER",
                "GROUP_MSG",
                "MANIFEST_PUSH",
                "MANIFEST_WANTS",
                "PAIR_CONFIRM",
                "PAIR_REJECT",
                "PAIR_REQUEST",
                "PEER_VERIFY_NOTICE",
                "PING",
                "PONG",
